import torch

def run(x, split_size_or_sections, dim=0):
    if isinstance(split_size_or_sections, int):
        dim_size = x.shape[dim]
        chunk = split_size_or_sections
        n_full = dim_size // chunk
        rem = dim_size - n_full * chunk
        sections = [chunk] * n_full + ([rem] if rem > 0 else [])
    else:
        sections = list(split_size_or_sections)
    if x.device.type == "cpu":
        return torch.split(x, sections, dim=dim)
    out_list = []
    for s in sections:
        shape = list(x.shape)
        shape[dim] = s
        out_list.append(torch.empty(shape, dtype=x.dtype, device=x.device))
    torch.split_with_sizes_copy(x, sections, dim=dim, out=out_list)
    return out_list
